class CustomHPOStrategy:
    """GP-EI-TR: Gaussian Process BO with adaptive-lengthscale Expected Improvement
    and trust-region candidate generation. Novel contributions: (1) marginal-
    likelihood-based lengthscale selection, (2) mixed candidate generation from
    random + elite perturbation + shrinking trust-region, (3) robust GP fitting."""
    def __init__(self, seed=42):
        self.seed = seed; self.rng = np.random.RandomState(seed)
    def _enc(self, c, sp):
        v = []
        for p in sp.params:
            val = c[p.name]
            if p.type == "categorical": v.append(p.choices.index(val) / max(len(p.choices) - 1, 1))
            elif p.log_scale: v.append(np.clip((np.log(val) - np.log(p.low)) / (np.log(p.high) - np.log(p.low)), 0, 1))
            else: v.append(np.clip((val - p.low) / (p.high - p.low), 0, 1))
        return np.array(v)
    def _dec(self, v, sp):
        c = {}
        for i, p in enumerate(sp.params):
            u = float(np.clip(v[i], 0, 1))
            if p.type == "categorical":
                c[p.name] = p.choices[min(int(round(u * max(len(p.choices) - 1, 1))), len(p.choices) - 1)]
            elif p.log_scale:
                raw = np.exp(np.log(p.low) + u * (np.log(p.high) - np.log(p.low)))
                c[p.name] = float(raw) if p.type == "float" else int(round(raw))
            else:
                raw = p.low + u * (p.high - p.low)
                c[p.name] = float(raw) if p.type == "float" else int(round(raw))
        return c
    def suggest(self, space, history, budget_left):
        n = len(history); d = space.dim
        if n < 2 * d + 1: return space.sample_uniform(self.rng), 1.0
        try:
            X = np.array([self._enc(t.config, space) for t in history])
            y = np.array([t.score for t in history])
            ym, ys = y.mean(), max(y.std(), 1e-8)
            yn = (y - ym) / ys; by = yn.max()
            sq = np.sum((X[:, None] - X[None, :]) ** 2, axis=2)
            bl, bls = -1e30, 0.5
            for ls in [0.1, 0.2, 0.5, 1.0, 2.0]:
                Kc = np.exp(-0.5 * sq / ls**2) + 0.01 * np.eye(n)
                try:
                    Lc = np.linalg.cholesky(Kc)
                    ac = np.linalg.solve(Lc.T, np.linalg.solve(Lc, yn))
                    ll = -0.5 * float(yn @ ac) - float(np.sum(np.log(np.diag(Lc))))
                    if ll > bl: bl, bls = ll, ls
                except: pass
            K = np.exp(-0.5 * sq / bls**2) + 0.01 * np.eye(n)
            L = np.linalg.cholesky(K)
            alpha = np.linalg.solve(L.T, np.linalg.solve(L, yn))
            bx = X[np.argmax(y)]; fr = n / (budget_left + n)
            be, bc = -1e30, None
            for _ in range(200):
                r = self.rng.rand()
                if r < 0.25: c = space.sample_uniform(self.rng)
                elif r < 0.55:
                    ti = np.argsort(y)[-max(1, n // 4):]
                    c = self._dec(np.clip(X[self.rng.choice(ti)] + self.rng.randn(d) * 0.15, 0, 1), space)
                else:
                    s = max(0.02, 0.15 * (1 - fr))
                    c = self._dec(np.clip(bx + self.rng.randn(d) * s, 0, 1), space)
                x = self._enc(c, space)
                ks = np.exp(-0.5 * np.sum((x - X)**2, 1) / bls**2)
                mu = float(ks @ alpha); vv = np.linalg.solve(L, ks)
                var = max(1.0 - float(vv @ vv), 1e-6)
                sig = np.sqrt(var); z = (mu - by) / sig
                ei = float((mu - by) * scipy_norm.cdf(z) + sig * scipy_norm.pdf(z))
                if ei > be: be, bc = ei, c
            return bc, 1.0
        except: return space.sample_uniform(self.rng), 1.0

